import{_ as e,c as l,o as i,a3 as r}from"./chunks/framework.BusRvirq.js";const u=JSON.parse('{"title":"릴리스 노트 및 변경 이력 (Changelog)","description":"엠파시 SyncSeries 플랫폼의 버전별 주요 기능 개선, 보안 업데이트 및 아키텍처 결정 기록(ADR)","frontmatter":{"title":"릴리스 노트 및 변경 이력 (Changelog)","description":"엠파시 SyncSeries 플랫폼의 버전별 주요 기능 개선, 보안 업데이트 및 아키텍처 결정 기록(ADR)","sort":70,"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/ecosystem/changelog.html"}]]},"headers":[],"relativePath":"ecosystem/changelog.md","filePath":"ko/ecosystem/changelog.md","lastUpdated":1789439372000}'),n={name:"ecosystem/changelog.md"};function o(t,a,s,c,h,d){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="엔터프라이즈-릴리스-노트-변경-이력" tabindex="-1">엔터프라이즈 릴리스 노트 &amp; 변경 이력 <a class="header-anchor" href="#엔터프라이즈-릴리스-노트-변경-이력" aria-label="Permalink to “엔터프라이즈 릴리스 노트 &amp; 변경 이력”">​</a></h1><p>SyncSeries의 버전별 주요 업데이트, 보안 패치, 성능 개선 및 아키텍처 변경 기록(Architecture Decision Records)을 투명하게 안내합니다.</p><hr><h2 id="v2-4-0-2026-03-01" tabindex="-1">[v2.4.0] - 2026-03-01 <a class="header-anchor" href="#v2-4-0-2026-03-01" aria-label="Permalink to “[v2.4.0] - 2026-03-01”">​</a></h2><h3 id="주요-신규-기능" tabindex="-1">주요 신규 기능 <a class="header-anchor" href="#주요-신규-기능" aria-label="Permalink to “주요 신규 기능”">​</a></h3><ul><li><strong>SyncVerse 중앙 관제탑(Control Tower) 고도화</strong>: <ul><li>멀티 에이전트 협업 MsgHub 기반 A2A(Agent-to-Agent) 이벤트 라우팅 엔진 탑재.</li><li>Server-Sent Events (SSE) 기반 실시간 원격 관제 스트리밍 지원.</li></ul></li><li><strong>3단계 HITL(Human-In-The-Loop) 안전 거버넌스 승인 파이프라인 정식 출시</strong>: <ul><li><code>LOW</code>, <code>MEDIUM</code>, <code>HIGH</code> 등급별 자동 실행 및 관리자 승인 게이트웨이 구현.</li></ul></li><li><strong>RFC 7807 Problem Details 표준 에러 프로토콜 전사 적용</strong>: <ul><li>가짜 정상(Fake Normalcy) 상태 위장을 원천 차단하고 구조화된 진단 정보 전파.</li></ul></li></ul><h3 id="보안-및-컴플라이언스" tabindex="-1">보안 및 컴플라이언스 <a class="header-anchor" href="#보안-및-컴플라이언스" aria-label="Permalink to “보안 및 컴플라이언스”">​</a></h3><ul><li>푸터 필수 사업자 공시 정보 완비 및 B2B 엔터프라이즈 서비스 이용약관(<code>terms.html</code>) 신설.</li><li>Zero Data Retention (데이터 미학습 보증) 정책 및 보안 백서 통합.</li><li>시스템 가동률 99.9% SLA 인디케이터 배지 연동.</li></ul><hr><h2 id="v2-3-0-2026-02-15" tabindex="-1">[v2.3.0] - 2026-02-15 <a class="header-anchor" href="#v2-3-0-2026-02-15" aria-label="Permalink to “[v2.3.0] - 2026-02-15”">​</a></h2><h3 id="주요-개선-사항" tabindex="-1">주요 개선 사항 <a class="header-anchor" href="#주요-개선-사항" aria-label="Permalink to “주요 개선 사항”">​</a></h3><ul><li><strong>SyncLLM FinOps 시맨틱 캐시 &amp; PII 마스킹 게이트웨이</strong>: <ul><li>코사인 유사도 0.95 이상 동일 질의에 대한 Redis 기반 무지연(12ms) 시맨틱 캐싱.</li><li>초당 2,500 RPS 처리 가능한 인라인 개인정보(PII) 실시간 난독화 필터 탑재.</li></ul></li><li><strong>지능형 가용성 자동 페일오버(Circuit Breaker)</strong>: <ul><li>원격 LLM 제공사(OpenAI, Anthropic, Bedrock) 연속 3회 장애 감지 시 50ms 이내 보조 백엔드로 무단절 전환.</li></ul></li></ul><hr><h2 id="v2-2-0-2026-01-20" tabindex="-1">[v2.2.0] - 2026-01-20 <a class="header-anchor" href="#v2-2-0-2026-01-20" aria-label="Permalink to “[v2.2.0] - 2026-01-20”">​</a></h2><h3 id="주요-개선-사항-1" tabindex="-1">주요 개선 사항 <a class="header-anchor" href="#주요-개선-사항-1" aria-label="Permalink to “주요 개선 사항”">​</a></h3><ul><li><strong>SyncEta Vision-LLM 4.0 셀렉터 자가 치유(Self-Healing) 엔진</strong>: <ul><li>DOM 변경 감지 시 시각적 바운딩 박스와 텍스트 앵커를 결합한 자가 복구 성공률 98.4% 달성.</li><li>비상교육 AIDT E2E 회귀 테스트 시간 4시간에서 45분으로 81% 단축 실증.</li></ul></li><li><strong>Playwright 분산 클러스터 멀티 워커 노드 연동</strong>: <ul><li>K8s 환경에서 수백 대의 브라우저 컨테이너를 동시 오케스트레이션하여 병렬 테스트 수행.</li></ul></li></ul><hr><h2 id="v2-1-0-2025-11-10" tabindex="-1">[v2.1.0] - 2025-11-10 <a class="header-anchor" href="#v2-1-0-2025-11-10" aria-label="Permalink to “[v2.1.0] - 2025-11-10”">​</a></h2><h3 id="주요-개선-사항-2" tabindex="-1">주요 개선 사항 <a class="header-anchor" href="#주요-개선-사항-2" aria-label="Permalink to “주요 개선 사항”">​</a></h3><ul><li><strong>SyncBoot Spring Boot 3.3 / Java 21 기반 MSA 프레임워크</strong>: <ul><li>분산 트랜잭션 일관성을 위한 Orchestrated Saga 패턴 및 보상 트랜잭션 자동 생성.</li><li>Virtual Threads(Loom) 적용으로 동시 I/O 처리량 300% 향상.</li><li>AgentScope Java (<code>io.agentscope:agentscope-harness</code>) 전사 표준 AI 프레임워크 연동.</li></ul></li></ul><hr><h2 id="v2-0-0-2025-09-01" tabindex="-1">[v2.0.0] - 2025-09-01 <a class="header-anchor" href="#v2-0-0-2025-09-01" aria-label="Permalink to “[v2.0.0] - 2025-09-01”">​</a></h2><h3 id="플래그십-상용-릴리스" tabindex="-1">플래그십 상용 릴리스 <a class="header-anchor" href="#플래그십-상용-릴리스" aria-label="Permalink to “플래그십 상용 릴리스”">​</a></h3><ul><li><strong>SyncSeries 전사 3-Layer 아키텍처 상용 릴리스</strong>: <ul><li>Layer 1: 거버넌스 및 자율 협업 계층 (SyncVerse, SyncInsight)</li><li>Layer 2: 도메인 특화 자율 에이전트 계층 (SyncEta, SyncBoot, SyncCMS, SyncCrawl, SyncLLM)</li><li>Layer 3: 플랫폼 공통 인프라 계층 (DB 3-File 구조, MCP JSON-RPC 버스)</li></ul></li><li><strong>엔터프라이즈 온프레미스(Air-Gapped) 폐쇄망 배포 팩 최초 출하</strong>.</li></ul>',24)])])}const m=e(n,[["render",o]]);export{u as __pageData,m as default};
